#!/usr/bin/env python3
"""Build the data note: LaTeX tables from the CSVs, version stamp, pdflatex twice."""
import csv, subprocess, re, datetime, zoneinfo
from pathlib import Path
HERE = Path(__file__).resolve().parent
tag = datetime.datetime.now(zoneinfo.ZoneInfo('America/Toronto')).strftime('%Y-%m-%d-%H-%M-%S')
def rows(n):
    with open(HERE / n, newline='', encoding='utf-8') as fh: return list(csv.DictReader(fh))
def esc(s): return str(s).replace('&', '\\&').replace('%', '\\%').replace('_', '\\_')
def f1(x): return f'{float(x):.1f}'
def f2(x): return f'{float(x):.2f}'
MAIN = '2012-2016 | 2017-2021'
O = rows('death_sites_percentiles.csv'); D = rows('deaths_by_decile.csv'); K = rows('deaths_caught_by_top_cells.csv'); T = rows('terrebonne_cells_percentiles.csv')
MEAS = {'all': 'all collisions', 'injury': 'injury collisions', 'bike': 'collisions with a bicycle', 'ped': 'collisions with a pedestrian victim'}
MODE = {'bike': 'cyclist killed', 'ped': 'pedestrian killed'}
out = ['% generated by build.py\n']
# Table 1: percentiles
out.append(r'\begin{table}[htbp]\centering\caption{Where the death sites of 2017--2021 sit in the distribution of the 2012--2016 record of all 100\,m cells with a record (17,593 cells): median percentile of the death sites, and the share of deaths at sites in the top tenth, the top quarter and the lower half. One cyclist death and two pedestrian deaths fell in cells with no earlier record and are outside the ranking.}\label{tab:pct}' '\n'
           r'\footnotesize\begin{tabular}{@{}l l r r r r@{}}\toprule Deaths & Earlier record measured as & Median percentile & Top tenth & Top quarter & Lower half\\ \midrule' '\n')
for r in O:
    if r['split'] == MAIN and r['cell_m'] == '100':
        out.append(f"{MODE[r['mode']]} ({r['deaths_at_cells_with_a_record']} of {r['deaths_in_after_window']}) & {MEAS[r['measure']]} & {f1(r['median_percentile'])} & {100*float(r['share_in_top_decile']):.0f}\\,\\% & {100*float(r['share_in_top_quarter']):.0f}\\,\\% & {100*float(r['share_below_median']):.0f}\\,\\%\\\\\n")
out.append(r'\bottomrule\end{tabular}\end{table}' '\n\n')
# Table 2: deciles
out.append(r'\begin{table}[htbp]\centering\caption{Deaths in 2017--2021 per 100 cells by decile of the cells’ 2012--2016 injury-collision count (ties broken by the count of all collisions, then at random with a fixed seed), with 95\,\% Poisson intervals. 100\,m cells, 1,759 or 1,760 per decile.}\label{tab:dec}' '\n'
           r'\footnotesize\begin{tabular}{@{}r r r r r r r@{}}\toprule Decile & Injury collisions 2012--2016 & \multicolumn{2}{c}{Cyclist killed} & \multicolumn{2}{c}{Pedestrian killed}\\ & (min--max) & deaths & per 100 cells (95\,\% CI) & deaths & per 100 cells (95\,\% CI)\\ \midrule' '\n')
dm = {(r['mode'], r['decile']): r for r in D if r['split'] == MAIN and r['cell_m'] == '100'}
for q in range(1, 11):
    b = dm[('bike', str(q))]; p = dm[('ped', str(q))]
    out.append(f"{q} & {b['min_injury']}--{b['max_injury']} & {b['deaths']} & {f2(b['deaths_per_100_cells'])} ({f2(b['ci_low'])}--{f2(b['ci_high'])}) & {p['deaths']} & {f2(p['deaths_per_100_cells'])} ({f2(p['ci_low'])}--{f2(p['ci_high'])})\\\\\n")
out.append(r'\bottomrule\end{tabular}\end{table}' '\n\n')
# Table 3: top k
out.append(r'\begin{table}[htbp]\centering\caption{Share of the 2017--2021 deaths that fell in the cells ranked in the top $k$\,\% by their 2012--2016 record (deaths at cells with no earlier record count as not caught).}\label{tab:top}' '\n'
           r'\footnotesize\begin{tabular}{@{}r r r r@{}}\toprule Top $k$\,\% of cells & Cells flagged & Cyclist deaths caught (of 13) & Pedestrian deaths caught (of 87)\\ \midrule' '\n')
km = {(r['mode'], r['top_percent_of_cells']): r for r in K if r['split'] == MAIN and r['cell_m'] == '100'}
for k in ('1', '2', '5', '10', '20', '30', '50'):
    b = km[('bike', k)]; p = km[('ped', k)]
    out.append(f"{k} & {int(b['cells_flagged']):,} & {b['deaths_caught']} ({100*float(b['share']):.0f}\\,\\%) & {p['deaths_caught']} ({100*float(p['share']):.0f}\\,\\%)\\\\\n")
out.append(r'\bottomrule\end{tabular}\end{table}' '\n\n')
# Table 4: sensitivity
out.append(r'\begin{table}[htbp]\centering\caption{The same quantities with 200\,m cells and with the split moved one year earlier: deaths in the top decile and in the bottom seven deciles, and the median percentile of the death sites (earlier record = injury collisions).}\label{tab:sens}' '\n'
           r'\footnotesize\setlength{\tabcolsep}{4pt}\begin{tabular}{@{}l r r r r r r@{}}\toprule Windows & Cell & \multicolumn{2}{c}{Cyclist killed} & \multicolumn{2}{c}{Pedestrian killed} & Median percentile\\ & & top decile & bottom seven & top decile & bottom seven & cyclist / pedestrian\\ \midrule' '\n')
for sp in dict.fromkeys(r['split'] for r in D):
    for c in ('100', '200'):
        dd = [r for r in D if r['split'] == sp and r['cell_m'] == c]
        def cnt(mode, cond): return sum(int(r['deaths']) for r in dd if r['mode'] == mode and cond(int(r['decile'])))
        tot = {m: [r for r in K if r['split'] == sp and r['cell_m'] == c and r['mode'] == m][0]['of_deaths'] for m in ('bike', 'ped')}
        oo = {r['mode']: r for r in O if r['split'] == sp and r['cell_m'] == c and r['measure'] == 'injury'}
        out.append(f"{esc(sp)} & {c}\\,m & {cnt('bike', lambda q: q == 10)} of {tot['bike']} & {cnt('bike', lambda q: q <= 7)} & {cnt('ped', lambda q: q == 10)} of {tot['ped']} & {cnt('ped', lambda q: q <= 7)} & {f1(oo['bike']['median_percentile'])} / {f1(oo['ped']['median_percentile'])}\\\\\n")
out.append(r'\bottomrule\end{tabular}\end{table}' '\n\n')
# Table 5: Terrebonne
out.append(r'\begin{table}[htbp]\centering\caption{Rue de Terrebonne on the same scale: the 2012--2016 record of the 100\,m cell holding each intersection, and its percentile among the 17,593 cells with a record.}\label{tab:terr}' '\n'
           r'\footnotesize\begin{tabular}{@{}l r r r r r r r@{}}\toprule Intersection & All & Injury & Bicycle & Pedestrian & Percentile (all) & Percentile (injury) & Top tenth\\ \midrule' '\n')
for r in T:
    if r['all'] == '' or r['all'] == 'nan': continue
    pa = f1(r['percentile_all']) if r['percentile_all'] not in ('', 'nan') else '--'; pi = f1(r['percentile_injury']) if r['percentile_injury'] not in ('', 'nan') else '--'
    out.append(f"{esc(r['location'])} & {int(float(r['all']))} & {int(float(r['injury']))} & {int(float(r['bike']))} & {int(float(r['ped']))} & {pa} & {pi} & {'yes' if r['in_top_decile_by_injury'] == 'True' else 'no'}\\\\\n")
out.append(r'\bottomrule\end{tabular}\end{table}' '\n')
(HERE / 'tables_generated.tex').write_text(''.join(out), encoding='utf-8')
tex = HERE / 'location_record_test_note_en.tex'
s = tex.read_text(encoding='utf-8'); s = re.sub(r'\\newcommand\{\\docversion\}\{[^}]*\}', r'\\newcommand{\\docversion}{%s}' % tag, s); tex.write_text(s, encoding='utf-8')
for _ in range(2): subprocess.run(['pdflatex', '-interaction=nonstopmode', '-halt-on-error', tex.name], cwd=HERE, check=True, stdout=subprocess.DEVNULL)
print('built', tex.with_suffix('.pdf').name, 'version', tag)
